'use client';
import {cameraQuality} from '@/lib/camera-quality';
import {useEffect,useRef,useState} from 'react';
export function DocumentCamera({onCapture,onCancel,disabled=false}:{onCapture:(file:File)=>Promise<boolean>;onCancel?:()=>void;disabled?:boolean}){
 const [automatic,setAutomatic]=useState(true),[hint,setHint]=useState('Hold the document steady for automatic scanning.');
 const captureLock=useRef(false),attempts=useRef(0),lastAttempt=useRef(0),stable=useRef(0),previous=useRef<Uint8Array|undefined>(undefined);
 const video=useRef<HTMLVideoElement|null>(null),stream=useRef<MediaStream|null>(null),sequence=useRef(0);
 const [open,setOpen]=useState(false),[starting,setStarting]=useState(false),[ready,setReady]=useState(false),[error,setError]=useState(''),[devices,setDevices]=useState<MediaDeviceInfo[]>([]),[device,setDevice]=useState(''),[facing,setFacing]=useState<'user'|'environment'>('environment');
 function release(){stream.current?.getTracks().forEach(t=>t.stop());stream.current=null;if(video.current)video.current.srcObject=null}
 function close(){onCancel?.();captureLock.current=false;sequence.current++;release();setOpen(false);setStarting(false);setReady(false)}
 // The cleanup intentionally stops the latest stream, including one opened after mount.
 // oxlint-disable-next-line react-hooks/exhaustive-deps
 useEffect(()=>{const hidden=()=>{if(document.hidden)close()};document.addEventListener('visibilitychange',hidden);return()=>{sequence.current++;release();document.removeEventListener('visibilitychange',hidden)}},[]);
 async function start(id?:string,side?:'user'|'environment'){
  const seq=++sequence.current;if(captureLock.current)onCancel?.();captureLock.current=false;lastAttempt.current=0;setHint('Hold the document steady for automatic scanning.');previous.current=undefined;stable.current=0;attempts.current=0;release();setOpen(true);setReady(false);setStarting(true);setError('');
  const preferred=side??(navigator.maxTouchPoints>1?'environment':'user');setFacing(preferred);
  try{if(!navigator.mediaDevices?.getUserMedia)throw Error('Open this site in a browser with camera support over HTTPS.');
   const next=await navigator.mediaDevices.getUserMedia({audio:false,video:{...(id?{deviceId:{exact:id}}:{facingMode:{ideal:preferred}}),width:{ideal:1920},height:{ideal:1080}}});
   if(seq!==sequence.current){next.getTracks().forEach(t=>t.stop());return}stream.current=next;const track=next.getVideoTracks()[0];setDevice(track?.getSettings().deviceId??'');if(video.current){video.current.srcObject=next;await video.current.play()}
   const cameras=await navigator.mediaDevices.enumerateDevices();if(seq===sequence.current)setDevices(cameras.filter(d=>d.kind==='videoinput'));
  }catch(e){if(seq===sequence.current){release();setReady(false);setError(e instanceof DOMException&&e.name==='NotAllowedError'?'Camera permission was denied. Allow camera access for this site in your browser, then try again.':e instanceof DOMException&&e.name==='NotFoundError'?'No camera was found. Connect a webcam or use a photo or ID scanner.':'Could not open this camera. Close other camera apps, select another camera, or upload a photo.')}}finally{if(seq===sequence.current)setStarting(false)}
 }
 async function capture(){const v=video.current;if(!v?.videoWidth||!v.videoHeight||disabled||captureLock.current)return;captureLock.current=true;setHint('Reading document…');const seq=sequence.current;
  try{const canvas=document.createElement('canvas');canvas.width=v.videoWidth;canvas.height=v.videoHeight;canvas.getContext('2d')?.drawImage(v,0,0);const blob=await new Promise<Blob|null>(resolve=>canvas.toBlob(resolve,'image/jpeg',.95));if(seq!==sequence.current)return;if(!blob)throw Error();const found=await onCapture(new File([blob],'document-photo.jpg',{type:'image/jpeg'}));if(seq!==sequence.current)return;if(found){close();return}attempts.current++;if(attempts.current>=3){setAutomatic(false);setHint('Automatic scanning paused. Reposition the ID, then turn it on again or capture manually.')}else setHint('Could not read enough details. Move closer, reduce glare, and hold steady to retry.');
  }catch{if(seq===sequence.current)setHint('Could not read this frame. Try manual capture or upload a photo.')}finally{if(seq===sequence.current){captureLock.current=false;lastAttempt.current=Date.now();stable.current=0;previous.current=undefined}}
 }
 const latest=useRef({disabled,capture});useEffect(()=>{latest.current={disabled,capture}});
 useEffect(()=>{if(!open||!ready||!automatic)return;const canvas=document.createElement('canvas');canvas.width=320;canvas.height=180;const context=canvas.getContext('2d',{willReadFrequently:true});if(!context)return;
  const timer=setInterval(()=>{const v=video.current;if(!v||!v.videoWidth||document.hidden||latest.current.disabled||captureLock.current||Date.now()-lastAttempt.current<3000)return;try{context.drawImage(v,0,0,320,180);const quality=cameraQuality(context.getImageData(0,0,320,180).data,320,180,previous.current);previous.current=quality.gray;if(!quality.canAttempt){stable.current=0;setHint(quality.reason);return}stable.current++;setHint(stable.current<3?'Hold still — automatic read in '+(3-stable.current)+'…':'Reading document…');if(stable.current>=3)void latest.current.capture()}catch{setAutomatic(false);setHint('Automatic scanning is unavailable. Use Capture & read document.')}},700);return()=>clearInterval(timer);
 },[open,ready,automatic]);
 return <div className="document-camera">{!open?<button type="button" className="primary" disabled={disabled} onClick={()=>void start()}>Open camera</button>:<><label className="pilot-check"><input type="checkbox" checked={automatic} disabled={disabled} onChange={e=>{attempts.current=0;stable.current=0;setAutomatic(e.target.checked)}}/>Auto-scan when clear and steady</label><output aria-live="polite">{hint}</output><video ref={video} autoPlay playsInline muted aria-label="Live document camera" onLoadedData={()=>setReady(true)} onPlaying={()=>setReady(true)} style={{width:'100%',maxHeight:320,objectFit:'contain',background:'#152033',borderRadius:12}}/><button type="button" className="primary" disabled={starting||!ready||disabled} onClick={()=>void capture()}>Read ID now</button><p>Fill the camera view with the document. Automatic scanning starts after a steady, sharp view; keep passport bottom lines visible.</p><label className="field">Camera<select value={device} disabled={starting||disabled} onChange={e=>void start(e.target.value)}>{!devices.length&&<option value="">Default camera</option>}{devices.map((d,i)=><option key={d.deviceId} value={d.deviceId}>{d.label||'Camera '+(i+1)}</option>)}</select></label><div className="form-grid"><button type="button" className="primary" disabled={starting||!ready||disabled} onClick={()=>void capture()}>Capture &amp; read document</button><button type="button" className="secondary" disabled={starting||disabled} onClick={()=>void start(undefined,facing==='environment'?'user':'environment')}>Switch front / rear</button><button type="button" className="secondary" onClick={close}>Close camera</button></div>{starting&&<output>Opening camera…</output>}</>}{error&&<p role="alert">{error}</p>}</div>
}
